import React, { useContext, useEffect, useState } from "react";
import GeneralContext from "./GeneralContext";
import {
  KeyboardArrowDown,
  KeyboardArrowUp,
  BarChartOutlined,
  MoreHoriz,
} from "@mui/icons-material";
import { Tooltip, Grow } from "@mui/material";

const WatchList = () => {
  const { watchlist } = useContext(GeneralContext);
  const [displayList, setDisplayList] = useState([]);

  // For demo, you can fetch live prices here and update displayList if needed.
  // For now, just set displayList = watchlist directly
  useEffect(() => {
    setDisplayList(watchlist);
  }, [watchlist]);

  return (
    <div className="watchlist-container">
      <ul className="list">
        {displayList.map((stock, index) => (
          <WatchListItem stock={stock} key={index} />
        ))}
      </ul>
    </div>
  );
};

export default WatchList;

const WatchListItem = ({ stock }) => {
  const [showActions, setShowActions] = useState(false);

  return (
    <li
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
      className="watchlist-item">
      <div className="item">
        <p>{stock.symbol}</p>
        {/* You can add price and percent change display here */}
      </div>
      {showActions && <WatchListActions uid={stock.symbol} />}
    </li>
  );
};

const WatchListActions = ({ uid }) => {
  const { openBuyWindow } = useContext(GeneralContext);

  return (
    <span className="actions">
      <Tooltip title="Buy (B)" placement="top" arrow TransitionComponent={Grow}>
        <button className="buy" onClick={() => openBuyWindow(uid, "BUY")}>
          Buy
        </button>
      </Tooltip>

      <Tooltip
        title="Sell (S)"
        placement="top"
        arrow
        TransitionComponent={Grow}>
        <button className="sell" onClick={() => openBuyWindow(uid, "SELL")}>
          Sell
        </button>
      </Tooltip>

      <Tooltip
        title="Analytics (A)"
        placement="top"
        arrow
        TransitionComponent={Grow}>
        <button className="action">
          <BarChartOutlined />
        </button>
      </Tooltip>

      <Tooltip title="More" placement="top" arrow TransitionComponent={Grow}>
        <button className="action">
          <MoreHoriz />
        </button>
      </Tooltip>
    </span>
  );
};
